    activeIdAfterSkip,
    activeId,
    nameErrorVisible,
    emailErrorVisible,
    phoneErrorVisible,
    statusText
  }, null, 2));

  await browser.close();

  if (violations.length) process.exit(1);
  if (activeIdAfterSkip !== 'main-content') process.exit(1);
  if (activeId !== 'full-name') process.exit(1);
  if (!nameErrorVisible || !emailErrorVisible || phoneErrorVisible) process.exit(1);
  if (statusText.trim() !== 'Message ready to send.') process.exit(1);
})();
