       color: #0f766e;
       font-weight: 600;
     }

     @media (max-width: 520px) {
       main {
         padding-top: 4.5rem;
       }

       .card {
         padding: 1rem;
       }
     }

     @media (prefers-reduced-motion: reduce) {
       html {
         scroll-behavior: auto;
       }

       *, *::before, *::after {
         animation-duration: 0.01ms !important;
         animation-iteration-count: 1 !important;
         transition-duration: 0.01ms !important;
         scroll-behavior: auto !important;
       }
     }

     @media (forced-colors: active) {
       .skip-link,
       .card,
       input,
       button {
         forced-color-adjust: auto;
       }

       input[aria-invalid="true"] {
         border-color: CanvasText;
       }
     }
   </style>
 </head>
 <body>
   <a class="skip-link" href="#main-content">Skip to main content</a>

   <main id="main-content" tabindex="-1">
     <div class="page-shell">
       <header class="hero">
         <span class="eyebrow">Support</span>
         <h1>Contact our support team</h1>
         <p>Send us your details and we’ll get back to you as soon as possible.</p>
       </header>

       <section class="card" aria-labelledby="support-form-title">
         <h2 id="support-form-title" class="sr-only">Support contact form</h2>
         <form id="support-form" novalidate>
           <div class="form-field">
             <label for="full-name">Full name <span class="required-mark" aria-hidden="true">*</span></label>
             <input
               id="full-name"
               name="fullName"
               type="text"
               autocomplete="name"
               required
               aria-describedby="full-name-error"
             >
             <p class="field-error" id="full-name-error" hidden>Error: Enter your full name.</p>
           </div>

           <div class="form-field">
             <label for="email-address">Email address <span class="required-mark" aria-hidden="true">*</span></label>
             <input
               id="email-address"
               name="emailAddress"
               type="email"
               autocomplete="email"
               required
               aria-describedby="email-address-error"
             >
             <p class="field-error" id="email-address-error" hidden>Error: Enter a valid email address, like name@example.com.</p>
           </div>

           <div class="form-field">
             <label for="phone-number">Phone number <span aria-hidden="true">(optional)</span></label>
             <input
               id="phone-number"
               name="phoneNumber"
               type="tel"
               autocomplete="tel"
               inputmode="tel"
               aria-describedby="phone-number-help phone-number-error"
             >
             <p class="field-help" id="phone-number-help">Format: +1 555 555 5555 or 555-555-5555.</p>
             <p class="field-error" id="phone-number-error" hidden>Error: Enter a phone number in the shown format.</p>
           </div>

           <div class="actions">
             <button type="submit">Send message</button>
             <p class="form-status" id="form-status" aria-live="polite"></p>
           </div>
         </form>
       </section>
     </div>
   </main>

   <script>
     const form = document.getElementById('support-form');
     const status = document.getElementById('form-status');
     const fields = {
       fullName: {
         input: document.getElementById('full-name'),
         error: document.getElementById('full-name-error'),
         validate: (value) => value.trim().length > 0
       },
       email: {
         input: document.getElementById('email-address'),
         error: document.getElementById('email-address-error'),
         validate: (value) => {
           if (!value.trim()) {
             return false;
           }

           return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value.trim());
         }
       },
       phone: {
         input: document.getElementById('phone-number'),
         error: document.getElementById('phone-number-error'),
         validate: (value) => {
           const trimmed = value.trim();

           if (!trimmed) {
             return true;
           }

           const cleaned = trimmed.replace(/[\s().-]/g, '');
           return /^\+?\d{7,15}$/.test(cleaned);
         }
       }
     };

     function setFieldState(field, isValid) {
       field.input.setAttribute('aria-invalid', String(!isValid));
       field.error.hidden = isValid;
     }

     function validateField(field) {
       const isValid = field.validate(field.input.value);
       setFieldState(field, isValid);
       return isValid;
     }

     function validateForm() {
       const results = Object.values(fields).map(validateField);
       return results.every(Boolean);
     }

     Object.values(fields).forEach((field) => {
       field.input.addEventListener('input', () => {
         if (field.input.getAttribute('aria-invalid') === 'true') {
           validateField(field);
         }
       });

       field.input.addEventListener('blur', () => {
         validateField(field);
       });
     });

     form.addEventListener('submit', (event) => {
       event.preventDefault();
       status.textContent = '';

       const isValid = validateForm();

       if (!isValid) {
         const firstInvalid = Object.values(fields).find((field) => field.input.getAttribute('aria-invalid') === 'true');
         if (firstInvalid) {
           firstInvalid.input.focus();
         }
         return;
       }

       status.textContent = 'Message ready to send.';
       form.reset();
       Object.values(fields).forEach((field) => setFieldState(field, true));
     });
   </script>
 </body>
 </html>

